    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context — addresses EF Core 9 breaking changes for Cosmos provider
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Document>(b =>
        {
            b.ToContainer("Documents");
            b.HasPartitionKey(d => d.PartitionKey);

            // BREAKING CHANGE FIX #1: EF Core 9 renamed the discriminator
            // property from "Discriminator" to "$type". Existing documents
            // still use "Discriminator", so we must explicitly configure it
            // to keep the old property name and string values.
            b.HasDiscriminator<string>("Discriminator")
                .HasValue<Document>("Document");
        });
    }
}

class Document
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public string Content { get; set; } = default!;
}

// BREAKING CHANGE FIX #2: EF Core 9 removed synchronous I/O for Cosmos.
// All queries must use async (ToListAsync, FirstOrDefaultAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Before (broken in EF Core 9):
    //   var docs = _db.Documents.Where(d => d.PartitionKey == pk).ToList();
    //
    // After (required fix — use async):
    public async Task<List<Document>> GetDocumentsAsync(string pk)
    {
        return await _db.Documents
            .Where(d => d.PartitionKey == pk)
            .ToListAsync();
    }
}

